1→//! Assistant client wrapper. Thin convenience layer on top of [`Transport`]
//! that normalises Assistant JSON-RPC responses into a `serde_json::Value`.

use crate::error::{AssistantError, Result};
use crate::transport::{Transport, TransportConfig};
use serde_json::{Value, json};
use std::sync::Arc;

#[derive(Clone)]
10→pub struct AssistantClient {
    transport: Arc<Transport>,
}

impl AssistantClient {
    pub async fn new(cfg: TransportConfig) -> Result<Self> {
        let transport = Transport::new(cfg).await?;
        Ok(Self {
            transport: Arc::new(transport),
        })
20→    }

    pub fn from_transport(transport: Arc<Transport>) -> Self {
        Self { transport }
    }

    pub fn transport(&self) -> &Transport {
        &self.transport
    }

30→    /// Invoke a named Assistant method.
    pub async fn call(&self, method: &str, params: Value) -> Result<Value> {
        let envelope = json!({
            "jsonrpc": "2.0",
            "id": uuid::Uuid::new_v4().to_string(),
            "method": method,
            "params": params,
        });
        let raw = self.transport.call(method, envelope).await?;
        unwrap_jsonrpc(raw)
40→    }
}

/// Strip JSON-RPC envelope. Accepts both `{result: ...}` and `{error: ...}`
/// shapes; if neither is present the raw value is returned as-is.
pub fn unwrap_jsonrpc(value: Value) -> Result<Value> {
    if let Some(err) = value.get("error") {
        let code = err.get("code").and_then(|c| c.as_i64()).unwrap_or(-32000);
        let message = err
            .get("message")
50→            .and_then(|m| m.as_str())
            .unwrap_or("assistant error")
            .to_string();
        return Err(match code {
            -32601 | 404 => AssistantError::NotFound(message),
            -32602 | 400 => AssistantError::InvalidRequest(message),
            401 => AssistantError::Unauthenticated(message),
            403 => AssistantError::Forbidden(message),
            -32603 | 500 => AssistantError::Internal(message),
            _ => AssistantError::Unknown(message),
60→        });
    }
    if let Some(result) = value.get("result") {
        return Ok(result.clone());
    }
    Ok(value)
}

#[cfg(test)]
mod tests {
70→    use super::*;

    #[test]
    fn unwrap_jsonrpc_returns_result() {
        let v = json!({"jsonrpc": "2.0", "id": "1", "result": {"x": 1}});
        let out = unwrap_jsonrpc(v).unwrap();
        assert_eq!(out, json!({"x": 1}));
    }

    #[test]
80→    fn unwrap_jsonrpc_maps_not_found() {
        let v = json!({"error": {"code": 404, "message": "no such agent"}});
        let err = unwrap_jsonrpc(v).unwrap_err();
        assert!(matches!(err, AssistantError::NotFound(_)));
    }

    #[test]
    fn unwrap_jsonrpc_returns_raw_when_no_envelope() {
        let v = json!({"agents": []});
        assert_eq!(unwrap_jsonrpc(v.clone()).unwrap(), v);
90→    }
}

1→//! Admission for the retired standalone Assistant compatibility transport.
//!
//! The canonical bridge verifies SID1 against the private sled, registered
//! principal, revocation state, and exact grants. This process cannot reuse
//! that complete receiver across the bridge-owned Cozo store lock, so it must
//! never turn asserted genesis, trace, public-key, or SID1 claims into access.

use tonic::{Request, Status};

10→pub const WIREGUARD_PUBKEY_HEADER: &str = "x-wireguard-pubkey";
const SEALED_ID_METADATA_KEY: &str = op_identity::sealed_id::HTTP_HEADER_NAME;
const ASSERTION_METADATA_KEY: &str = "x-oracle-identity-assertion-bin";

/// Retained for callers that name the former extension type. No standalone
/// request receives this extension while canonical admission is unavailable.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct WireGuardIdentity {
    pub pubkey: String,
    pub footprint: String,
20→    pub session_id: String,
}

/// Reject legacy asserted headers and every unverified SID1/OIA1 credential.
/// A structurally valid SID1 is deliberately insufficient for authorization.
#[allow(clippy::result_large_err)]
pub fn wireguard_auth_interceptor(req: Request<()>) -> Result<Request<()>, Status> {
    if req.metadata().contains_key(ASSERTION_METADATA_KEY) {
        return Err(Status::unauthenticated(
            "standalone Assistant transport cannot verify OIA1",
30→        ));
    }
    let mut values = req
        .metadata()
        .get_all_bin(SEALED_ID_METADATA_KEY)
        .into_iter();
    let value = values
        .next()
        .ok_or_else(|| Status::unauthenticated("SID1 credential required"))?;
    if values.next().is_some() {
40→        return Err(Status::unauthenticated("multiple SID1 credentials"));
    }
    let wire = value
        .to_bytes()
        .map_err(|_| Status::unauthenticated("malformed SID1 metadata"))?;
    op_identity::sealed_id::SealedId::open(&wire)
        .map_err(|_| Status::unauthenticated("invalid SID1 credential"))?;
    Err(Status::unavailable(
        "standalone Assistant RPCs disabled until canonical identity and grant admission is shared",
    ))
50→}

#[cfg(test)]
mod tests {
    use super::*;
    use tonic::{Code, metadata::MetadataValue};

    #[test]
    fn missing_identity_is_rejected() {
        let error = wireguard_auth_interceptor(Request::new(())).unwrap_err();
60→        assert_eq!(error.code(), Code::Unauthenticated);
    }

    #[test]
    fn matching_legacy_genesis_and_pubkey_are_not_credentials() {
        let mut request = Request::new(());
        request.metadata_mut().insert(
            "x-ghostbridge-genesis",
            MetadataValue::from_static("known-genesis"),
        );
70→        request.metadata_mut().insert(
            WIREGUARD_PUBKEY_HEADER,
            MetadataValue::from_static("known-pubkey"),
        );
        let error = wireguard_auth_interceptor(request).unwrap_err();
        assert_eq!(error.code(), Code::Unauthenticated);
    }

    #[test]
    fn structurally_valid_sid1_is_still_denied_without_canonical_checks() {
80→        let claims = op_identity::sealed_id::SealedId {
            principal_id: "principal".into(),
            principal_kind: "wireguard-principal".into(),
            session_id: "session".into(),
            wireguard_pubkey: "pubkey".into(),
            session_genesis: "genesis".into(),
            trace_id: "trace".into(),
            schema_version: 1,
            issued_at: 1,
            expires_at: 0,
90→            arrival_timestamp: 1,
            chain_head_at_arrival: "chain".into(),
            catalog_hash_at_arrival: "catalog".into(),
            head_timestamp_at_arrival: 1,
            transport_scope: "grpc".into(),
            nextdns: None,
        };
        let mut request = Request::new(());
        request.metadata_mut().insert_bin(
            SEALED_ID_METADATA_KEY,
100→            MetadataValue::from_bytes(&claims.seal().unwrap()),
        );
        let error = wireguard_auth_interceptor(request).unwrap_err();
        assert_eq!(error.code(), Code::Unavailable);
    }
}

1→//! Shared helpers for converting between JSON values returned by the Assistant
//! HTTP API and the proto types generated by tonic.

use prost_types::value::Kind;
use prost_types::{ListValue, Struct, Timestamp, Value as PValue};
use serde_json::{Map, Value};

pub fn str_field(v: &Value, key: &str) -> String {
    v.get(key)
10→        .and_then(|s| s.as_str())
        .unwrap_or_default()
        .to_string()
}

pub fn u32_field(v: &Value, key: &str) -> u32 {
    v.get(key).and_then(|n| n.as_u64()).unwrap_or(0) as u32
}

pub fn u64_field(v: &Value, key: &str) -> u64 {
20→    v.get(key).and_then(|n| n.as_u64()).unwrap_or(0)
}

pub fn bool_field(v: &Value, key: &str) -> bool {
    v.get(key).and_then(|n| n.as_bool()).unwrap_or(false)
}

pub fn opt_str(v: &Value, key: &str) -> Option<String> {
    v.get(key).and_then(|s| s.as_str()).map(String::from)
}
30→
pub fn string_list(v: &Value, key: &str) -> Vec<String> {
    v.get(key)
        .and_then(|s| s.as_array())
        .map(|a| {
            a.iter()
                .filter_map(|s| s.as_str().map(String::from))
                .collect()
        })
        .unwrap_or_default()
40→}

pub fn ts_field(v: &Value, key: &str) -> Option<Timestamp> {
    let raw = v.get(key)?;
    if let Some(s) = raw.as_str()
        && let Ok(dt) = chrono::DateTime::parse_from_rfc3339(s)
    {
        return Some(Timestamp {
            seconds: dt.timestamp(),
            nanos: dt.timestamp_subsec_nanos() as i32,
50→        });
    }
    if let Some(secs) = raw.as_i64() {
        return Some(Timestamp {
            seconds: secs,
            nanos: 0,
        });
    }
    None
}
60→
pub fn struct_to_json(s: Struct) -> Value {
    let mut map = Map::with_capacity(s.fields.len());
    for (k, v) in s.fields {
        map.insert(k, pvalue_to_json(v));
    }
    Value::Object(map)
}

pub fn pvalue_to_json(p: PValue) -> Value {
70→    match p.kind {
        None | Some(Kind::NullValue(_)) => Value::Null,
        Some(Kind::BoolValue(b)) => Value::Bool(b),
        Some(Kind::NumberValue(n)) => serde_json::Number::from_f64(n)
            .map(Value::Number)
            .unwrap_or(Value::Null),
        Some(Kind::StringValue(s)) => Value::String(s),
        Some(Kind::StructValue(s)) => struct_to_json(s),
        Some(Kind::ListValue(ListValue { values })) => {
            Value::Array(values.into_iter().map(pvalue_to_json).collect())
80→        }
    }
}

pub fn json_to_struct(v: Value) -> Struct {
    match v {
        Value::Object(map) => Struct {
            fields: map
                .into_iter()
                .map(|(k, v)| (k, json_to_pvalue(v)))
90→                .collect(),
        },
        _ => Struct::default(),
    }
}

pub fn json_to_pvalue(v: Value) -> PValue {
    let kind = match v {
        Value::Null => Kind::NullValue(0),
        Value::Bool(b) => Kind::BoolValue(b),
100→        Value::Number(n) => Kind::NumberValue(n.as_f64().unwrap_or(0.0)),
        Value::String(s) => Kind::StringValue(s),
        Value::Array(arr) => Kind::ListValue(ListValue {
            values: arr.into_iter().map(json_to_pvalue).collect(),
        }),
        Value::Object(map) => Kind::StructValue(Struct {
            fields: map
                .into_iter()
                .map(|(k, v)| (k, json_to_pvalue(v)))
                .collect(),
110→        }),
    };
    PValue { kind: Some(kind) }
}

pub fn opt_struct(v: &Value, key: &str) -> Option<Struct> {
    v.get(key).cloned().map(json_to_struct)
}

#[cfg(test)]
120→mod tests {
    use super::*;
    use serde_json::json;

    #[test]
    fn struct_roundtrip() {
        let original = json!({"a": 1.0, "b": "x", "c": [true, null]});
        let s = json_to_struct(original.clone());
        let back = struct_to_json(s);
        assert_eq!(back, original);
130→    }

    #[test]
    fn ts_parses_rfc3339() {
        let v = json!({"t": "2024-01-02T03:04:05Z"});
        let t = ts_field(&v, "t").unwrap();
        assert!(t.seconds > 0);
    }
}

